import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
import {createComponentFilter,createComponentProvenance} from '../sites/filter.mjs';
import {createSiteSession} from '../sites/model.mjs';
import {createMediaLibrary} from '../sites/media.mjs';
import {savedSiteTooltip} from '../sites/library-label.mjs';
import {componentTooltip,MEDIA_FORMAT_LABELS} from '../sites/file-tooltip.mjs';
const html=readFileSync(new URL('../sites/index.html',import.meta.url),'utf8');
const item=(id,type,label,value='')=>({id:'ain-'+id,type,label,value,alt:'',animation:'none',duration:1.2,delay:0});
const items=[item(0,'text','Portada'),item(1,'image','Portada principal','https://media.org/photo.jpg'),item(2,'video','Portada vídeo','https://media.org/clip.mp4'),item(3,'graphic','Logotipo'),item(4,'background','Fondo','https://media.org/bg.jpg')];
function setup(onChange=()=>{},getMediaName,isLocked,getMediaMime){
  const dom=new JSDOM(html),doc=dom.window.document;doc.getElementById('options-panel').hidden=false;doc.getElementById('project-options').hidden=false;
  Object.defineProperty(dom.window,'localStorage',{get(){throw Error('El filtro no guarda preferencias');}});
  return {dom,doc,filter:createComponentFilter({document:doc,onChange,getMediaName,isLocked,getMediaMime}),search:doc.getElementById('filter'),type:doc.getElementById('component-type'),visibility:doc.getElementById('component-visibility'),animation:doc.getElementById('component-animation'),provenance:doc.getElementById('component-provenance'),description:doc.getElementById('component-description'),format:doc.getElementById('component-format'),resetButton:doc.getElementById('reset-component-filters'),status:doc.getElementById('component-results')};
}
test('la ayuda cuenta sólo selectores no predeterminados con cero, singular y plural, también plegados y sin coincidencias',()=>{
  let ui;ui=setup(()=>ui.filter.apply(items,()=>false,undefined,'ain-0'));const {dom,doc,filter,search,type,visibility,animation,provenance,description,format}=ui,button=doc.getElementById('toggle-component-selectors'),controls=[type,visibility,animation,provenance,description,format],values=['image','hidden','rise','added','described','image/jpeg'];
  const check=(prefix,count)=>{const label=prefix+' selectores de filtro · '+count+' '+(count===1?'selector activo':'selectores activos');assert.equal(button.title,label);assert.equal(button.getAttribute('aria-label'),label);assert.equal(button.textContent.trim(),'');assert.equal(button.getAttribute('aria-controls'),'component-selectors');};check('Ocultar',0);search.value='consulta sin resultados';search.dispatchEvent(new dom.window.Event('input'));check('Ocultar',0);
  for(let i=0;i<controls.length;i++){controls[i].value=values[i];controls[i].dispatchEvent(new dom.window.Event('change'));check('Ocultar',i+1);}const state=doc.getElementById('component-results').outerHTML,before=controls.map(n=>n.value);button.click();check('Mostrar',6);assert.equal(button.getAttribute('aria-expanded'),'false');assert.equal(doc.getElementById('component-results').outerHTML,state);assert.deepEqual(controls.map(n=>n.value),before);
  filter.reset();check('Mostrar',0);format.value='image/jpeg';filter.apply(items,()=>false);check('Mostrar',1);button.click();check('Ocultar',1);assert.equal(button.getAttribute('aria-expanded'),'true');
});
test('la ayuda se sincroniza al restablecer, localizar, abrir la vista y bloquear sin alterar filtros, foco o resultados',()=>{
  let ui,locked=false;ui=setup(()=>ui.filter.apply(items,()=>false),undefined,()=>locked);const {doc,filter,type,resetButton,status}=ui,button=doc.getElementById('toggle-component-selectors');type.value='image';filter.apply(items,()=>false);button.click();assert.equal(button.title,'Mostrar selectores de filtro · 1 selector activo');button.focus();const state=status.outerHTML;locked=true;filter.syncAvailability();assert.equal(button.disabled,true);assert.equal(button.title,'Mostrar selectores de filtro · 1 selector activo');assert.equal(type.value,'image');assert.equal(status.outerHTML,state);assert.equal(doc.activeElement,button);
  locked=false;filter.syncAvailability();assert.equal(button.disabled,false);resetButton.click();assert.equal(button.title,'Mostrar selectores de filtro · 0 selectores activos');assert.equal(doc.getElementById('component-selectors').hidden,true);doc.getElementById('components').innerHTML='<button data-item="ain-0"><strong>Selección</strong></button>';filter.locate('ain-0');assert.equal(button.title,'Mostrar selectores de filtro · 0 selectores activos');assert.equal(doc.getElementById('component-selectors').hidden,true);filter.expandSelectors();assert.equal(button.title,'Ocultar selectores de filtro · 0 selectores activos');assert.equal(button.getAttribute('aria-expanded'),'true');
});
test('el plegado empieza desplegado, agrupa sólo seis selectores y usa SVG con nombre accesible, tooltip y estado correctos',()=>{
  const {doc}=setup(),group=doc.getElementById('component-selectors'),button=doc.getElementById('toggle-component-selectors');assert.equal(group.hidden,false);assert.deepEqual([...group.querySelectorAll('select')].map(n=>n.id),['component-type','component-visibility','component-animation','component-provenance','component-description','component-format']);
  assert.equal(button.type,'button');assert.equal(button.textContent.trim(),'');assert.equal(button.querySelectorAll('svg').length,1);assert.equal(button.getAttribute('aria-expanded'),'true');assert.equal(button.getAttribute('aria-controls'),group.id);assert.equal(button.getAttribute('aria-label'),'Ocultar selectores de filtro · 0 selectores activos');assert.equal(button.title,'Ocultar selectores de filtro · 0 selectores activos');for(const id of ['filter','locate-selection','reset-component-filters','component-results','components'])assert.equal(group.contains(doc.getElementById(id)),false);
  button.click();assert.equal(group.hidden,true);assert.equal(button.getAttribute('aria-expanded'),'false');assert.equal(button.getAttribute('aria-label'),'Mostrar selectores de filtro · 0 selectores activos');assert.equal(button.title,'Mostrar selectores de filtro · 0 selectores activos');button.click();assert.equal(group.hidden,false);assert.equal(button.getAttribute('aria-expanded'),'true');
});
test('plegar y desplegar conserva filtros, coincidencias, selección, nodos y foco sin repintar ni mover scroll o lienzo',()=>{
  let changes=0;const {doc,filter,type,visibility,animation,provenance,description,format,search,status}=setup(()=>changes++),group=doc.getElementById('component-selectors'),button=doc.getElementById('toggle-component-selectors');type.value='image';visibility.value='hidden';animation.value='rise';provenance.value='added';description.value='described';format.value='image/jpeg';search.value=' consulta escrita ';filter.apply(items,()=>false,undefined,'ain-0');doc.getElementById('components').innerHTML='<button data-item="ain-0" aria-pressed="true"><strong>Selección</strong><span>Texto</span></button>';doc.getElementById('fields').textContent='Inspector intacto';doc.getElementById('draft-frame').srcdoc='<p>Lienzo intacto</p>';doc.getElementById('options-panel').scrollTop=47;doc.getElementById('components').scrollTop=31;doc.documentElement.scrollTop=19;
  const controls=[type,visibility,animation,provenance,description,format,search],values=controls.map(n=>n.value),nodes=[...group.children],row=doc.getElementById('components').firstChild,state=status.outerHTML;filter.reset=filter.locate=()=>{throw Error('No restablecer o localizar');};button.focus();for(let i=0;i<2;i++){button.click();assert.deepEqual(controls.map(n=>n.value),values);assert.deepEqual([...group.children],nodes);assert.equal(doc.getElementById('components').firstChild,row);assert.equal(status.outerHTML,state);assert.equal(doc.activeElement,button);assert.equal(changes,0);assert.equal(doc.getElementById('fields').textContent,'Inspector intacto');assert.equal(doc.getElementById('draft-frame').srcdoc,'<p>Lienzo intacto</p>');assert.equal(doc.getElementById('options-panel').scrollTop,47);assert.equal(doc.getElementById('components').scrollTop,31);assert.equal(doc.documentElement.scrollTop,19);}
});
test('Restablecer y Localizar funcionan plegados; abrir la vista de selectores es independiente y el bloqueo se respeta',()=>{
  let ui,locked=false,changes=0;ui=setup(()=>{changes++;ui.filter.apply(items,()=>false);},undefined,()=>locked);const {doc,filter,type,resetButton,status}=ui,group=doc.getElementById('component-selectors'),button=doc.getElementById('toggle-component-selectors');button.click();type.value='image';filter.apply(items,()=>false);resetButton.click();assert.equal(changes,1);assert.equal(type.value,'all');assert.equal(group.hidden,true);assert.equal(status.textContent,'Filtros restablecidos. 5 componentes.');doc.getElementById('components').innerHTML='<button data-item="ain-0"><strong>Selección</strong></button>';assert.equal(filter.locate('ain-0'),true);assert.equal(group.hidden,true);assert.match(status.textContent,/Selección localizada/);
  locked=true;filter.syncAvailability();assert.equal(button.disabled,true);button.click();assert.equal(group.hidden,true);locked=false;filter.syncAvailability();assert.equal(button.disabled,false);type.value='video';filter.expandSelectors();assert.equal(group.hidden,false);assert.equal(type.value,'video');assert.equal(changes,1);assert.equal(button.getAttribute('aria-expanded'),'true');
});
test('formato accesible comparte MIME y coherencia con la ayuda; Todos conserva el orden y no consulta descriptores',()=>{
  const formats=[['image/png','PNG'],['image/jpeg','JPEG'],['image/webp','WebP'],['image/gif','GIF'],['image/avif','AVIF'],['video/mp4','MP4'],['video/webm','WebM']],mimes=new Map(),valid=formats.map(([mime],index)=>{const ref='ain-local:'+(index+1).toString(16).repeat(64);mimes.set(ref,mime);return item(index,mime.startsWith('image/')?'image':'video','JPEG PNG .mp4 .png',ref);});
  const invalid=[item(20,'image','Remota','https://example.org/photo.png'),item(21,'graphic','SVG',valid[0].value),item(22,'video','Tipo incoherente',valid[0].value),item(23,'image','Sin descriptor','ain-local:'+'c'.repeat(64)),item(24,'image','Objeto','ain-local:'+'d'.repeat(64)),item(25,'video','Ref inválida','ain-local:no')];mimes.set(invalid[4].value,{toString(){throw Error('No convertir MIME');}});const media=[...valid,...invalid],before=JSON.stringify(media),calls=[],getMime=ref=>{calls.push(ref);return mimes.get(ref);}, {doc,filter,format,status}=setup(()=>{},()=> 'nombre-equivocado.txt',undefined,getMime);
  assert.ok(doc.querySelector('label[for="component-format"]').textContent.startsWith('Formato del archivo'));assert.equal(format.getAttribute('aria-controls'),'components');assert.equal(format.getAttribute('aria-describedby'),'component-results');assert.equal(format.value,'all');assert.deepEqual([...format.options].map(o=>[o.value,o.text]),[['all','Todos'],...formats]);assert.deepEqual(Object.entries(MEDIA_FORMAT_LABELS),formats);
  assert.deepEqual(filter.apply(media,()=>false),media);assert.deepEqual(calls,[]);for(const [index,[mime,label]]of formats.entries()){format.value=mime;assert.deepEqual(filter.apply(media,()=>false),[valid[index]]);assert.equal(status.hidden,false);assert.equal(status.textContent,'1 de 13 componentes');assert.ok(componentTooltip(valid[index],'Detalle',()=> 'nombre-equivocado.txt',undefined,getMime).endsWith('Formato del archivo: '+label));}
  assert.ok(!calls.includes(invalid[0].value)&&!calls.includes(invalid[5].value));format.value='all';assert.deepEqual(filter.apply(media,()=>false),media);assert.equal(status.hidden,true);assert.equal(JSON.stringify(media),before);
});
