  const a='ain-local:'+'a'.repeat(64),b='ain-local:'+'b'.repeat(64),media=[item(0,'graphic','Selección'),{...item(1,'image','Introduccio\u0301n año',a),alt:'Foto del pingüino',hidden:true,animation:'rise'},{...item(2,'image','Introducción año',b),alt:'',hidden:true,animation:'rise'},item(3,'video','Cabecera',a)],before=JSON.stringify(media),getMime=ref=>ref===a?'image/jpeg':'image/png',{filter,type,visibility,animation,provenance,description,format,search,status}=setup(()=>{},()=> 'captura.png',undefined,getMime),hidden=i=>i.hidden===true,origin=i=>i.type==='graphic'?'imported':'added';
  type.value='image';visibility.value='hidden';animation.value='rise';provenance.value='added';description.value='described';format.value='image/jpeg';search.value=' PINGUINO captura INTRODUCCION AN\u0303O ';assert.deepEqual(filter.apply(media,hidden,origin,'ain-0').map(i=>i.id),['ain-1']);assert.match(status.textContent,/La selección actual no aparece/);filter.apply(media,hidden,origin,'ain-1');assert.equal(status.textContent,'1 de 4 componentes');
  format.value='image/png';assert.deepEqual(filter.apply(media,hidden,origin,'ain-1'),[]);assert.match(status.textContent,/No hay coincidencias.*La selección actual/);description.value='undescribed';search.value='captura introduccion año';assert.deepEqual(filter.apply(media,hidden,origin).map(i=>i.id),['ain-2']);type.value='video';assert.deepEqual(filter.apply(media,hidden,origin),[]);assert.equal(type.value,'video');assert.equal(format.value,'image/png');
